def gate_list(text):
    out = []
    for row in text.split('\n'):
        for tok in row.split('-'):
            tok = tok.strip()
            if tok and tok != 'I':
                out.append(tok.split('#')[0])
    return out

def size(text):
    rows = [r for r in text.split('\n') if r.strip()]
    return [len(rows), len(rows[0].split('-'))]

