practice.solution:
def label(i, n):
    s = ''
    for _ in range(n):
        s = str(i % 2) + s
        i = i // 2
    return s

def agree(samples):
    n = 0
    for s in samples:
        if s[0] == s[1]:
            n += 1
    return round(n / len(samples), 2)

def tally(samples):
    d = {}
    for s in samples:
        d[s] = d.get(s, 0) + 1
    return sorted([[k, v] for k, v in d.items()])

